/**
 * Publishing package: captions, hashtags, alt text, destination, credits, and
 * rights warnings for a finished creative. Curated templates with the
 * creative's real values filled in. Nothing here is generated by a model and
 * the UI must not say it is.
 */
import { templateFamily } from './families.js'
import { deriveRights } from './creativeModel.js'

const BASE_TAGS = ['faneqo', 'independentartist', 'musicians', 'bandlife']
const FAMILY_TAGS = {
  'artist-spotlight': ['artistspotlight', 'newmusic', 'supportlocalmusic'],
  'song-spotlight': ['newmusic', 'nowplaying', 'newrelease', 'singlerelease'],
  'product-showcase': ['musicmarketing', 'artistpage', 'linkinbio', 'fanlist'],
  'type-statement': ['musicmarketing', 'musicindustry', 'diymusician'],
  'education': ['musicmarketing', 'diymusician', 'musicbusiness', 'bandtips'],
  insights: ['musicmarketing', 'musicindustry', 'diymusician', 'fanengagement'],
  'show-promo': ['livemusic', 'concert', 'tour', 'showtonight'],
}

function tag(text) {
  const clean = String(text || '').toLowerCase().replace(/[^a-z0-9]/g, '')
  return clean ? clean : null
}

function uniq(list) {
  return [...new Set(list.filter(Boolean))]
}

function longDate(iso) {
  const m = String(iso || '').match(/^(\d{4})-(\d{2})-(\d{2})/)
  if (!m) return ''
  const months = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
  return `${months[Number(m[2]) - 1]} ${Number(m[3])}`
}

/** End a fragment with a period unless it already ends in punctuation. */
function sentence(text) {
  const raw = String(text || '').trim()
  if (!raw) return ''
  return /[.!?…"”]$/.test(raw) ? raw : `${raw}.`
}

function linesOf(content) {
  return (content.lines || []).map((l) => (typeof l === 'string' ? l : l.text)).join(' ').replace(/\s+/g, ' ').trim()
}

function captionsFor(creative) {
  const c = creative.content || {}
  const artist = creative.artistName || c.artistName || ''
  const url = destinationFor(creative)
  switch (creative.templateId) {
    case 'artist-spotlight': {
      const line = c.description ? ` ${sentence(c.description)}` : ''
      const song = c.songTitle ? ` Featured song: “${c.songTitle}”.` : ''
      return {
        instagram: `Artist Spotlight: ${artist}.${line}${song}\n\nMusic, shows, and the fan list — all on one page. Link in bio.`,
        facebook: `Artist Spotlight: ${artist}.${line}${song}\n\nEverything ${artist} is doing, on one page: ${url}`,
        alt: `${artist} artist spotlight. Photograph of ${artist}${c.songTitle ? ` with the featured song ${c.songTitle}` : ''}. Faneqo.`,
      }
    }
    case 'song-spotlight': {
      const title = c.title || 'the featured song'
      const line = c.line ? ` ${sentence(c.line)}` : ''
      return {
        instagram: `“${title}” — ${artist}.${line}\n\nPlay it on the artist page. Link in bio.`,
        facebook: `“${title}” — ${artist}.${line}\n\nListen on the artist page: ${url}`,
        alt: `Album artwork for ${title} by ${artist}. Faneqo song spotlight.`,
      }
    }
    case 'product-showcase': {
      const head = `${c.headlineTop || ''} ${c.headlineAccent || ''}`.replace(/\s+/g, ' ').trim()
      const support = c.support ? ` ${sentence(c.support)}` : ''
      return {
        instagram: `${head}${support}\n\nFaneqo is one page for your music, video, links, shows, and fans. Link in bio.`,
        facebook: `${head}${support}\n\nBuild yours: ${url}`,
        alt: `${head}. A Faneqo artist page showing ${excerptLabel(c.excerpt)}${artist ? ` for ${artist}` : ''}.`,
      }
    }
    case 'type-statement': {
      const statement = linesOf(c)
      const support = c.support ? `\n\n${c.support}` : ''
      return {
        instagram: `${statement}${support}\n\nFaneqo. Link in bio.`,
        facebook: `${statement}${support}\n\n${url}`,
        alt: `Typographic statement reading “${statement}”. Faneqo.`,
      }
    }
    case 'education': {
      const headline = c.cover?.headline || 'Notes for musicians'
      const points = (c.slides || []).slice(0, 5).map((s, i) => `${i + 1}. ${s.title}`).join('\n')
      return {
        instagram: `${headline}\n\n${points}\n\nSave this for your next release or show. More at the link in bio.`,
        facebook: `${headline}\n\n${points}\n\n${url}`,
        alt: `Carousel: ${headline}. ${(c.slides || []).length} slides of advice for independent musicians. Faneqo.`,
      }
    }
    case 'insights': {
      const headline = sentence(c.statement)
      const take = c.insight && c.style === 'playbook' ? `\n\n${c.insight}` : ''
      const support = c.support ? `\n\n${c.support}` : ''
      return {
        instagram: `${headline}${take}${support}\n\nFaneqo. Link in bio.`,
        facebook: `${headline}${take}${support}\n\n${url}`,
        alt: `Music industry insight: “${c.statement || 'A note for musicians'}”. Faneqo.`,
      }
    }
    case 'show-promo': {
      const show = c.show || {}
      const place = [show.venue, show.city, show.state].filter(Boolean).join(', ')
      const when = longDate(show.date)
      const details = [when, place].filter(Boolean).join(' · ')
      const ticket = show.link ? `\n\nTickets: ${show.link}` : ''
      return {
        instagram: `${artist} live${show.city ? ` in ${show.city}` : ''}.${details ? `\n\n${details}` : ''}${show.priceLine ? `\n${show.priceLine}` : ''}\n\nDetails and tickets at the link in bio.`,
        facebook: `${artist} live${show.city ? ` in ${show.city}` : ''}.${details ? `\n\n${details}` : ''}${show.priceLine ? `\n${show.priceLine}` : ''}${ticket}\n\n${url}`,
        alt: `${artist} show poster${when ? `, ${when}` : ''}${place ? ` at ${place}` : ''}. Faneqo.`,
      }
    }
    default:
      return { instagram: '', facebook: '', alt: '' }
  }
}

function excerptLabel(id) {
  return { page: 'the artist page', song: 'the featured song', fanlist: 'the fan list', shows: 'upcoming shows', gallery: 'a photo gallery' }[id] || 'the artist page'
}

export function destinationFor(creative) {
  const c = creative.content || {}
  if (creative.templateId === 'show-promo' && c.show?.link && /^https?:\/\//i.test(c.show.link)) return c.show.link
  if (creative.snapshot?.pageUrl) return creative.snapshot.pageUrl
  if (creative.bandSlug) return `https://faneqo.com/${creative.bandSlug}`
  return 'https://faneqo.com'
}

export function hashtagsFor(creative) {
  const c = creative.content || {}
  const artist = tag(creative.artistName || c.artistName)
  const genre = tag(creative.snapshot?.genre)
  const city = creative.templateId === 'show-promo' ? tag(c.show?.city) : null
  const cityMusic = city ? `${city}music` : null
  return uniq([artist, ...(FAMILY_TAGS[creative.templateId] || []), genre, city, cityMusic, ...BASE_TAGS]).slice(0, 14).map((t) => `#${t}`)
}

export function buildPublishingPackage(creative) {
  const family = templateFamily(creative?.templateId)
  if (!family) return null
  const captions = captionsFor(creative)
  const rights = deriveRights(creative)
  const hashtags = hashtagsFor(creative)
  return {
    instagram: `${captions.instagram}\n\n${hashtags.join(' ')}`.trim(),
    facebook: captions.facebook.trim(),
    hashtags,
    altText: captions.alt.trim(),
    url: destinationFor(creative),
    credits: rights.credits,
    warnings: rights.warnings,
    rightsStatus: rights.rightsStatus,
    note: 'Curated caption templates filled from this creative. Edit before posting. Previews and captions are not posted automatically.',
  }
}
